window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b238241ae7acbacf"]={"versions": [{"id": "FIG-b238241ae7acbacf", "releases": ["R1.3.0", "R17-10_R1.2.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm zur Erfassung und Weiterleitung von VFB-Trace-Nachrichten (Virtual Function Bus Tracing) innerhalb eines Steuergeräts (ECU) bis zur externen Protokollierung auf einem Diagnose- oder Entwicklungsrechner. Das Diagramm verortet die Interaktion zwischen Applikationsebene, AUTOSAR Runtime Environment (RTE) und dem Diagnostic Log and Trace (DLT) Basissoftware-Modul.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU (Steuergerät)</strong>: Übergeordnete Systemgrenze mit folgenden internen Entitäten:\n<ul class=\"fig-list\"><li><strong>Application (dreifach dargestellt)</strong>: Anwendungs-Softwarekomponenten (SWCs), die über Port-basierte Kommunikation miteinander interagieren.\n</li><li><strong>Runtime Environment (RTE)</strong>: Kommunikationsinfrastruktur (rot hinterlegt), die den Virtual Function Bus (VFB) auf dem Steuergerät realisiert und Schnittstellen für VFB-Tracing bereitstellt.\n</li><li><strong>DLT</strong>: Basissoftware-Modul (gelb hinterlegt) zur Filterung, Pufferung und Kapselung von Log- und Trace-Meldungen in DLT-Nachrichtenformate.\n</li></ul>\n</li><li><strong>Externer Logging-Knoten (Laptop-Symbol)</strong>: Externes Test- oder Analysewerkzeug (DLT Client / Log Viewer) zur persistenten Aufzeichnung.\n</li><li><strong>Schnittstellen &amp; Verbindungswege</strong>:\n<ul class=\"fig-list\"><li>VFB-Kommunikationspfade zwischen den Applications durch die Runtime Environment.\n</li><li>Gerades Trace-Signal vom VFB/RTE zum DLT-Modul.\n</li><li>Externe serielle bzw. Netzwerk-Kommunikationsverbindung (DLT-Protokollkanal) vom DLT-Modul zum externen Rechner.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der sequenzielle Ablauf ist in vier nummerierten Schritten definiert:</p>\n<ol class=\"fig-list\"><li><strong>Send TraceMessage</strong>: Bei VFB-Ereignissen oder Datenübertragungen zwischen Software-Komponenten generiert die Runtime Environment eine VFB-Trace-Nachricht und übergibt diese an das DLT-Modul.\n</li><li><strong>Filter / Generate DLT Message</strong>: Das DLT-Modul filtert eingehende Trace-Meldungen basierend auf aktuellen Filterkonfigurationen und erzeugt standardkonforme DLT-Nachrichten.\n</li><li><strong>Send DLT TraceMessage</strong>: Das DLT-Modul überträgt die serialisierten DLT-Trace-Nachrichten über eine Kommunikationsschnittstelle an das externe Werkzeug.\n</li><li><strong>Store DLT Messages</strong>: Das externe Werkzeug empfängt und speichert die DLT-Nachrichten zur Offline-Analyse und Diagnose.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Verhaltenskette für VFB-Tracing im Kontext des AUTOSAR Log and Trace Protokolls. Implementierungen der RTE müssen bei aktivierter VFB-Tracing-Konfiguration Trace-Hooks bedienen und Daten an das DLT-Modul übergeben. Das DLT-Modul muss Filtermechanismen implementieren und Nachrichten über standardisierte DLT-Frames auskoppeln. Der Ablauf erfordert eine synchrone oder asynchrone Schnittstelle zwischen RTE-Trace-Hooks und DLT-Pufferung.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7f93f6d471ecd1d0", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm zur Erfassung und Weiterleitung von VFB-Trace-Nachrichten (Virtual Function Bus Tracing) innerhalb eines Steuergeräts (ECU) bis zur externen Protokollierung auf einem Diagnose- oder Entwicklungsrechner. Das Diagramm verortet die Interaktion zwischen Applikationsebene, AUTOSAR Runtime Environment (RTE) und dem Diagnostic Log and Trace (DLT) Basissoftware-Modul.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU (Steuergerät)</strong>: Übergeordnete Systemgrenze mit folgenden internen Entitäten:\n<ul class=\"fig-list\"><li><strong>Application (dreifach dargestellt)</strong>: Anwendungs-Softwarekomponenten (SWCs), die über Port-basierte Kommunikation miteinander interagieren.\n</li><li><strong>Runtime Environment (RTE)</strong>: Kommunikationsinfrastruktur (rot hinterlegt), die den Virtual Function Bus (VFB) auf dem Steuergerät realisiert und Schnittstellen für VFB-Tracing bereitstellt.\n</li><li><strong>DLT</strong>: Basissoftware-Modul (gelb hinterlegt) zur Filterung, Pufferung und Kapselung von Log- und Trace-Meldungen in DLT-Nachrichtenformate.\n</li></ul>\n</li><li><strong>Externer Logging-Knoten (Laptop-Symbol)</strong>: Externes Test- oder Analysewerkzeug (DLT Client / Log Viewer) zur persistenten Aufzeichnung.\n</li><li><strong>Schnittstellen &amp; Verbindungswege</strong>:\n<ul class=\"fig-list\"><li>VFB-Kommunikationspfade zwischen den Applications durch die Runtime Environment.\n</li><li>Gerades Trace-Signal vom VFB/RTE zum DLT-Modul.\n</li><li>Externe serielle bzw. Netzwerk-Kommunikationsverbindung (DLT-Protokollkanal) vom DLT-Modul zum externen Rechner.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der sequenzielle Ablauf ist in vier nummerierten Schritten definiert:</p>\n<ol class=\"fig-list\"><li><strong>Send TraceMessage</strong>: Bei VFB-Ereignissen oder Datenübertragungen zwischen Software-Komponenten generiert die Runtime Environment eine VFB-Trace-Nachricht und übergibt diese an das DLT-Modul.\n</li><li><strong>Filter / Generate DLT Message</strong>: Das DLT-Modul filtert eingehende Trace-Meldungen basierend auf aktuellen Filterkonfigurationen und erzeugt standardkonforme DLT-Nachrichten.\n</li><li><strong>Send DLT TraceMessage</strong>: Das DLT-Modul überträgt die serialisierten DLT-Trace-Nachrichten über eine Kommunikationsschnittstelle an das externe Werkzeug.\n</li><li><strong>Store DLT Messages</strong>: Das externe Werkzeug empfängt und speichert die DLT-Nachrichten zur Offline-Analyse und Diagnose.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Verhaltenskette für VFB-Tracing im Kontext des AUTOSAR Log and Trace Protokolls. Implementierungen der RTE müssen bei aktivierter VFB-Tracing-Konfiguration Trace-Hooks bedienen und Daten an das DLT-Modul übergeben. Das DLT-Modul muss Filtermechanismen implementieren und Nachrichten über standardisierte DLT-Frames auskoppeln. Der Ablauf erfordert eine synchrone oder asynchrone Schnittstelle zwischen RTE-Trace-Hooks und DLT-Pufferung.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ecbc7a4876051a4b", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm zur Erfassung und Weiterleitung von VFB-Trace-Nachrichten (Virtual Function Bus Tracing) innerhalb eines Steuergeräts (ECU) bis zur externen Protokollierung auf einem Diagnose- oder Entwicklungsrechner. Das Diagramm verortet die Interaktion zwischen Applikationsebene, AUTOSAR Runtime Environment (RTE) und dem Diagnostic Log and Trace (DLT) Basissoftware-Modul.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU (Steuergerät)</strong>: Übergeordnete Systemgrenze mit folgenden internen Entitäten:\n<ul class=\"fig-list\"><li><strong>Application (dreifach dargestellt)</strong>: Anwendungs-Softwarekomponenten (SWCs), die über Port-basierte Kommunikation miteinander interagieren.\n</li><li><strong>Runtime Environment (RTE)</strong>: Kommunikationsinfrastruktur (rot hinterlegt), die den Virtual Function Bus (VFB) auf dem Steuergerät realisiert und Schnittstellen für VFB-Tracing bereitstellt.\n</li><li><strong>DLT</strong>: Basissoftware-Modul (gelb hinterlegt) zur Filterung, Pufferung und Kapselung von Log- und Trace-Meldungen in DLT-Nachrichtenformate.\n</li></ul>\n</li><li><strong>Externer Logging-Knoten (Laptop-Symbol)</strong>: Externes Test- oder Analysewerkzeug (DLT Client / Log Viewer) zur persistenten Aufzeichnung.\n</li><li><strong>Schnittstellen &amp; Verbindungswege</strong>:\n<ul class=\"fig-list\"><li>VFB-Kommunikationspfade zwischen den Applications durch die Runtime Environment.\n</li><li>Gerades Trace-Signal vom VFB/RTE zum DLT-Modul.\n</li><li>Externe serielle bzw. Netzwerk-Kommunikationsverbindung (DLT-Protokollkanal) vom DLT-Modul zum externen Rechner.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der sequenzielle Ablauf ist in vier nummerierten Schritten definiert:</p>\n<ol class=\"fig-list\"><li><strong>Send TraceMessage</strong>: Bei VFB-Ereignissen oder Datenübertragungen zwischen Software-Komponenten generiert die Runtime Environment eine VFB-Trace-Nachricht und übergibt diese an das DLT-Modul.\n</li><li><strong>Filter / Generate DLT Message</strong>: Das DLT-Modul filtert eingehende Trace-Meldungen basierend auf aktuellen Filterkonfigurationen und erzeugt standardkonforme DLT-Nachrichten.\n</li><li><strong>Send DLT TraceMessage</strong>: Das DLT-Modul überträgt die serialisierten DLT-Trace-Nachrichten über eine Kommunikationsschnittstelle an das externe Werkzeug.\n</li><li><strong>Store DLT Messages</strong>: Das externe Werkzeug empfängt und speichert die DLT-Nachrichten zur Offline-Analyse und Diagnose.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Verhaltenskette für VFB-Tracing im Kontext des AUTOSAR Log and Trace Protokolls. Implementierungen der RTE müssen bei aktivierter VFB-Tracing-Konfiguration Trace-Hooks bedienen und Daten an das DLT-Modul übergeben. Das DLT-Modul muss Filtermechanismen implementieren und Nachrichten über standardisierte DLT-Frames auskoppeln. Der Ablauf erfordert eine synchrone oder asynchrone Schnittstelle zwischen RTE-Trace-Hooks und DLT-Pufferung.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e6476cd88e5ca192", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm zur Erfassung und Weiterleitung von Kommunikations- und VFB-Trace-Nachrichten über eine plattformübergreifende Middleware (Classic RTE oder Adaptive Kommunikations-Middleware) und ein DLT-Modul (Classic DLT oder Adaptive <code>ara::log</code>) an einen externen Logging-Client.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU</strong>: Übergeordneter Steuergeräteknoten mit folgenden Komponenten:\n<ul class=\"fig-list\"><li><strong>Application (dreifach dargestellt)</strong>: Software-Komponenten bzw. Adaptive Applications.\n</li><li><strong>Middleware</strong>: Plattformunabhängig generalisierte Kommunikationsschicht (blau hinterlegt; umfasst Classic RTE sowie Adaptive Middleware), die Kommunikationsströme der Applikationen bündelt.\n</li><li><strong>Dlt module (DLT or ara::log)</strong>: Zentrales Logging- und Tracing-Modul (gelb hinterlegt), das entweder als Classic AUTOSAR DLT-Basissoftware oder als Adaptive AUTOSAR <code>ara::log</code> realisiert ist.\n</li></ul>\n</li><li><strong>Externer Testknoten (Laptop-Symbol)</strong>: Externes DLT-Empfangswerkzeug zur Speicherung von Trace-Nachrichten.\n</li><li><strong>Schnittstellen &amp; Verbindungswege</strong>:\n<ul class=\"fig-list\"><li>Schnittstellenanbindung der Applications an die Middleware.\n</li><li>Abgewinkelter Trace-Kanal von der Middleware-Ebene in die Seitenflanke des Dlt module.\n</li><li>Externe Datenübertragungsstrecke vom Dlt module zum Analysewerkzeug.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in vier nummerierte Phasen:</p>\n<ol class=\"fig-list\"><li><strong>provide trace message</strong>: Die Middleware erfasst relevante Interaktionsereignisse der Applikationen und übergibt die Trace-Information an das Dlt module.\n</li><li><strong>filter/generate Dlt message</strong>: Das Dlt module wendet Filterregeln an und generiert standardisierte Dlt-Nachrichten.\n</li><li><strong>send Dlt message</strong>: Das Dlt module übermittelt die generierte Dlt-Nachricht über die Transportschnittstelle an die Außenwelt.\n</li><li><strong>store Dlt message</strong>: Das externe Tool empfängt die Dlt-Nachricht und speichert sie ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die normative Konvergenz von Classic Platform (DLT) und Adaptive Platform (<code>ara::log</code>) bezüglich der Trace-Erfassung auf Middleware-Ebene. Middleware-Implementierungen müssen standardisierte Trace-Events an das jeweilige Logging-Subsystem bereitstellen („provide trace message“). Auf Schnittstellenebene sind beide Implementierungsformen austauschbar konform zu den Protokoll- und Filterregeln für DLT-Nachrichten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-02985e60103375bf", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm zur Erfassung und Weiterleitung von Kommunikations- und VFB-Trace-Nachrichten über eine plattformübergreifende Middleware (Classic RTE oder Adaptive Kommunikations-Middleware) und ein DLT-Modul (Classic DLT oder Adaptive <code>ara::log</code>) an einen externen Logging-Client.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU</strong>: Übergeordneter Steuergeräteknoten mit folgenden Komponenten:\n<ul class=\"fig-list\"><li><strong>Application (dreifach dargestellt)</strong>: Software-Komponenten bzw. Adaptive Applications.\n</li><li><strong>Middleware</strong>: Plattformunabhängig generalisierte Kommunikationsschicht (blau hinterlegt; umfasst Classic RTE sowie Adaptive Middleware), die Kommunikationsströme der Applikationen bündelt.\n</li><li><strong>Dlt module (DLT or ara::log)</strong>: Zentrales Logging- und Tracing-Modul (gelb hinterlegt), das entweder als Classic AUTOSAR DLT-Basissoftware oder als Adaptive AUTOSAR <code>ara::log</code> realisiert ist.\n</li></ul>\n</li><li><strong>Externer Testknoten (Laptop-Symbol)</strong>: Externes DLT-Empfangswerkzeug zur Speicherung von Trace-Nachrichten.\n</li><li><strong>Schnittstellen &amp; Verbindungswege</strong>:\n<ul class=\"fig-list\"><li>Schnittstellenanbindung der Applications an die Middleware.\n</li><li>Abgewinkelter Trace-Kanal von der Middleware-Ebene in die Seitenflanke des Dlt module.\n</li><li>Externe Datenübertragungsstrecke vom Dlt module zum Analysewerkzeug.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in vier nummerierte Phasen:</p>\n<ol class=\"fig-list\"><li><strong>provide trace message</strong>: Die Middleware erfasst relevante Interaktionsereignisse der Applikationen und übergibt die Trace-Information an das Dlt module.\n</li><li><strong>filter/generate Dlt message</strong>: Das Dlt module wendet Filterregeln an und generiert standardisierte Dlt-Nachrichten.\n</li><li><strong>send Dlt message</strong>: Das Dlt module übermittelt die generierte Dlt-Nachricht über die Transportschnittstelle an die Außenwelt.\n</li><li><strong>store Dlt message</strong>: Das externe Tool empfängt die Dlt-Nachricht und speichert sie ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die normative Konvergenz von Classic Platform (DLT) und Adaptive Platform (<code>ara::log</code>) bezüglich der Trace-Erfassung auf Middleware-Ebene. Middleware-Implementierungen müssen standardisierte Trace-Events an das jeweilige Logging-Subsystem bereitstellen („provide trace message“). Auf Schnittstellenebene sind beide Implementierungsformen austauschbar konform zu den Protokoll- und Filterregeln für DLT-Nachrichten.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b238241ae7acbacf", "to": "FIG-7f93f6d471ecd1d0", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7f93f6d471ecd1d0", "to": "FIG-ecbc7a4876051a4b", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ecbc7a4876051a4b", "to": "FIG-b238241ae7acbacf", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7f93f6d471ecd1d0", "to": "FIG-e6476cd88e5ca192", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Runtime Environment -&gt; Middleware</strong>: Die Laufzeitumgebungskomponente wurde von „Runtime Environment“ zu „Middleware“ generalisiert, um Adaptive Platform abzudecken.\n</li><li><strong>DLT -&gt; Dlt module (DLT or ara::log)</strong>: Die Trace-Senke wurde von „DLT“ zu „Dlt module (DLT or ara::log)“ erweitert.\n</li><li><strong>Signalpfad Schritt 1</strong>: Die Pfeilführung verläuft nun von der Schnittstelle unterhalb der Middleware im 90-Grad-Winkel seitlich in das DLT-Modul (beschriftet mit „provide trace message“ statt „Send TraceMessage“).\n</li><li><strong>Signalbezeichnungen (Schritte 2 bis 4)</strong>: \n<ul class=\"fig-list\"><li>Schritt 2: „filter/generate Dlt message“ statt „Filter / Generate DLT Message“\n</li><li>Schritt 3: „send Dlt message“ statt „Send DLT TraceMessage“\n</li><li>Schritt 4: „store Dlt message“ statt „Store DLT Messages“ (Einzahl statt Mehrzahl, geänderte Typografie)\n</li></ul>\n</li></ul>"}, {"from": "FIG-e6476cd88e5ca192", "to": "FIG-02985e60103375bf", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
